>+			hpa_list->phys[j] = page_to_phys(page + i + j);
>+
>+		ret = tdx_ext_mem_add(virt_to_page(hpa_list), nents);
>+		/*
>+		 * No SEAMCALLs to reclaim the added pages. For simple error
>+		 * handling, leak all pages.
